  ('00000001-0000-4000-8000-000000000001', 'silk', '{"templateKey":"silk","tokens":{"colors":{"primary":"#7A1F2B","accent":"#C9A227","background":"#FBF8F3","text":"#1E1A16"},"fonts":{"heading":"Cormorant Garamond","body":"Inter"},"radius":"none"},"branding":{"logoKey":null,"faviconKey":null,"tagline":"Handwoven silks from Kanchipuram and Varanasi"},"announcement":"Free shipping across India on orders above ₹5,000","sections":[{"type":"hero","props":{"eyebrow":"Wedding season 2026","subheading":"Kanjivaram and Banarasi silks, woven by master weavers and finished by hand.","ctaLabel":"Explore the collection","ctaHref":"/c/kanjivaram","bannerIds":["00000001-0006-4000-8000-000000000001","00000001-0006-4000-8000-000000000002"]}},{"type":"categoryTiles","props":{"title":"Shop by weave","limit":6}},{"type":"featuredProducts","props":{"title":"Bridal & festive","subtitle":"Heirloom silks for the days you will remember.","source":"featured","limit":8}},{"type":"promoBanner","props":{"bannerId":"00000001-0006-4000-8000-000000000003","eyebrow":"Everyday handloom","heading":"Cottons and linens under ₹4,000","body":"Breathable weaves from Chettinad, Mangalagiri and Bengal, made for long summer days.","ctaLabel":"Shop cotton","ctaHref":"/c/cotton"}},{"type":"featuredProducts","props":{"title":"New on the loom","source":"newest","limit":4}},{"type":"brandStory","props":{"eyebrow":"Our story","heading":"Three generations of weaving","body":"Tara Weaves began as a single loom in Kanchipuram. Today we work with forty weaving families, paying fair wages and keeping traditional techniques like korvai and temple borders alive. Every saree is checked by hand before it reaches you."}},{"type":"testimonials","props":{}}]}'::jsonb, '{"templateKey":"silk","tokens":{"colors":{"primary":"#7A1F2B","accent":"#C9A227","background":"#FBF8F3","text":"#1E1A16"},"fonts":{"heading":"Cormorant Garamond","body":"Inter"},"radius":"none"},"branding":{"logoKey":null,"faviconKey":null,"tagline":"Handwoven s