insert into public.store_pages (id, tenant_id, slug, title, body, is_published, created_at, updated_at) values
  ('00000001-0007-4000-8000-000000000001', '00000001-0000-4000-8000-000000000001', 'about', 'About us', 'Tara Weaves began as a single loom in Kanchipuram. Today we work with forty weaving families, paying fair wages and keeping traditional techniques like korvai and temple borders alive.
insert into public.products (id, tenant_id, name, slug, description, price_mode, price_paise, compare_at_paise, status, attributes, is_featured, seo, created_at, updated_at) values
  ('00000001-0003-4000-8000-000000000001', '00000001-0000-4000-8000-000000000001', 'Ruby Temple-Border Kanjivaram', 'ruby-temple-border-kanjivaram', 'A classic ruby Kanjivaram with a contrast temple border and a rich pallu of peacocks and mango motifs, woven in pure mulberry silk.', 'fixed', 2450000, null, 'active', '{"fabric":"Pure mulberry silk","zari":"Silver zari, gold polished","colour":"Red","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Wedding","care":"Dry clean only"}'::jsonb, true, '{}'::jsonb, '2026-10-06T10:00:00.000Z', '2026-10-06T10:00:00.000Z'),
  ('00000001-0003-4000-8000-000000000002', '00000001-0000-4000-8000-000000000001', 'Bridal Peacock Kanjivaram', 'bridal-peacock-kanjivaram', 'Our heaviest bridal weave: an emerald body with an all-over peacock jaal and a 9-inch korvai border. Made to order; price confirmed on WhatsApp.', 'on_request', null, null, 'active', '{"fabric":"Pure mulberry silk","zari":"Pure gold zari","colour":"Green","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Bridal","care":"Dry clean only"}'::jsonb, true, '{}'::jsonb, '2026-11-10T10:00:00.000Z', '2026-11-10T10:00:00.000Z'),
  ('00000001-0003-4000-8000-000000000003', '00000001-0000-4000-8000-000000000001', 'Mustard Korvai Kanjivaram', 'mustard-korvai-kanjivaram', 'Turmeric-gold body with an interlocked korvai border in deep maroon. Light enough to wear all day.', 'fixed', 1890000, 2100000, 'active', '{"fabric":"Pure mulberry silk","zari":"Silver zari, gold polished","colour":"Yellow","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Festive","care":"Dry clean only"}'::jsonb, false, '{}'::jsonb, '2026-09-16T10:00:00.000Z', '2026-09-16T10:00:00.000Z'),
  ('00000001-0003-4000-8000-000000000004', '00000001-0000-4000-8000-000000000001', 'Midnight Brocade Banarasi', 'midnight-brocade-banarasi', 'Midnight-blue katan silk with a dense floral brocade and a shimmering kadhwa pallu.', 'fixed', 1540000, null, 'active', '{"fabric":"Katan silk","zari":"Antique gold zari","colour":"Blue","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Festive","care":"Dry clean only"}'::jsonb, true, '{}'::jsonb, '2026-11-03T10:00:00.000Z', '2026-11-03T10:00:00.000Z'),
  ('00000001-0003-4000-8000-000000000005', '00000001-0000-4000-8000-000000000001', 'Rose Kadhwa Banarasi', 'rose-kadhwa-banarasi', 'Soft rose georgette woven with kadhwa buttis, finished with a scalloped zari border.', 'fixed', 1280000, null, 'active', '{"fabric":"Georgette","zari":"Silver zari","colour":"Pink","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Party","care":"Dry clean only"}'::jsonb, false, '{}'::jsonb, '2026-10-21T10:00:00.000Z', '2026-10-21T10:00:00.000Z'),
  ('00000001-0003-4000-8000-000000000006', '00000001-0000-4000-8000-000000000001', 'Ivory Tissue Banarasi', 'ivory-tissue-banarasi', 'An heirloom ivory tissue saree with real gold zari. Woven to order in about six weeks; price confirmed on WhatsApp.', 'on_request', null, null, 'active', '{"fabric":"Tissue silk","zari":"Pure gold zari","colour":"Ivory","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Bridal","care":"Dry clean only"}'::jsonb, true, '{}'::jsonb, '2026-11-12T10:00:00.000Z', '2026-11-12T10:00:00.000Z'),
  ('00000001-0003-4000-8000-000000000007', '00000001-0000-4000-8000-000000000001', 'Lavender Soft Silk', 'lavender-soft-silk', 'A featherlight soft silk in lavender with a slim gold border, easy to drape and easy to carry.', 'fixed', 745000, null, 'active', '{"fabric":"Soft silk","zari":"Copper zari","colour":"Purple","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Festive","care":"Dry clean only"}'::jsonb, true, '{}'::jsonb, '2026-11-07T10:00:00.000Z', '2026-11-07T10:00:00.000Z'),
  ('00000001-0003-4000-8000-000000000008', '00000001-0000-4000-8000-000000000001', 'Teal Zari-Butta Soft Silk', 'teal-zari-butta-soft-silk', 'Deep teal soft silk scattered with tiny zari buttas and a contrast magenta border.', 'fixed', 690000, 790000, 'active', '{"fabric":"Soft silk","zari":"Copper zari","colour":"Teal","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Festive","care":"Dry clean only"}'::jsonb, false, '{}'::jsonb, '2026-10-16T10:00:00.000Z', '2026-10-16T10:00:00.000Z'),
  ('00000001-0003-4000-8000-000000000009', '00000001-0000-4000-8000-000000000001', 'Coral Soft Silk', 'coral-soft-silk', 'A bright coral soft silk with a plain body and a woven pallu. Restocking soon.', 'fixed', 620000, null, 'active', '{"fabric":"Soft silk","zari":"Copper zari","colour":"Orange","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Party","care":"Dry clean only"}'::jsonb, false, '{}'::jsonb, '2026-09-26T10:00:00.000Z', '2026-09-26T10:00:00.000Z'),
  ('00000001-0003-4000-8000-00000000000a', '00000001-0000-4000-8000-000000000001', 'Indigo Kalamkari Cotton', 'indigo-kalamkari-cotton', 'Hand-painted kalamkari on soft mul cotton, dyed in natural indigo.', 'fixed', 245000, null, 'active', '{"fabric":"Mul cotton","colour":"Blue","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Not included","occasion":"Everyday","care":"Hand wash cold, separately"}'::jsonb, true, '{}'::jsonb, '2026-11-13T10:00:00.000Z', '2026-11-13T10:00:00.000Z'),
  ('00000001-0003-4000-8000-00000000000b', '00000001-0000-4000-8000-000000000001', 'Chettinad Checks Cotton', 'chettinad-checks-cotton', 'Bold Chettinad checks in rust and mustard, with a crisp hand that softens with every wash.', 'fixed', 189000, null, 'active', '{"fabric":"Chettinad cotton","colour":"Orange","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Everyday","care":"Hand wash cold, separately"}'::jsonb, false, '{}'::jsonb, '2026-10-28T10:00:00.000Z', '2026-10-28T10:00:00.000Z'),
  ('00000001-0003-4000-8000-00000000000c', '00000001-0000-4000-8000-000000000001', 'Sage Mangalagiri Cotton', 'sage-mangalagiri-cotton', 'Sage-green Mangalagiri cotton with a nizam zari border; a workday favourite.', 'fixed', 215000, null, 'active', '{"fabric":"Mangalagiri cotton","colour":"Green","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Everyday","care":"Hand wash cold, separately"}'::jsonb, false, '{}'::jsonb, '2026-10-11T10:00:00.000Z', '2026-10-11T10:00:00.000Z'),
  ('00000001-0003-4000-8000-00000000000d', '00000001-0000-4000-8000-000000000001', 'Natural Handloom Linen', 'natural-handloom-linen', 'Undyed handloom linen with a fine silver zari border. Cool, crisp and quietly elegant.', 'fixed', 365000, null, 'active', '{"fabric":"Linen","colour":"Natural","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Office","care":"Dry clean recommended"}'::jsonb, false, '{}'::jsonb, '2026-11-09T10:00:00.000Z', '2026-11-09T10:00:00.000Z'),
  ('00000001-0003-4000-8000-00000000000e', '00000001-0000-4000-8000-000000000001', 'Charcoal Linen with Silver Border', 'charcoal-linen-silver-border', 'Charcoal linen with a broad silver border. Only a few left from this weave.', 'fixed', 399000, null, 'active', '{"fabric":"Linen","colour":"Grey","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Office","care":"Dry clean recommended"}'::jsonb, false, '{}'::jsonb, '2026-10-24T10:00:00.000Z', '2026-10-24T10:00:00.000Z'),
  ('00000001-0003-4000-8000-00000000000f', '00000001-0000-4000-8000-000000000001', 'Blush Floral Organza', 'blush-floral-organza', 'Sheer blush organza with hand-embroidered florals and a delicate scalloped edge.', 'fixed', 485000, null, 'active', '{"fabric":"Silk organza","colour":"Pink","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Party","care":"Dry clean only"}'::jsonb, true, '{}'::jsonb, '2026-11-14T10:00:00.000Z', '2026-11-14T10:00:00.000Z'),
  ('00000001-0003-4000-8000-000000000010', '00000001-0000-4000-8000-000000000001', 'Sky Blue Embroidered Organza', 'sky-embroidered-organza', 'Powder-blue organza with tonal thread embroidery and a satin-finished border.', 'fixed', 540000, 620000, 'active', '{"fabric":"Silk organza","colour":"Blue","length":"5.5 m saree + 0.8 m blouse piece","blouse":"Included, unstitched","occasion":"Party","care":"Dry clean only"}'::jsonb, false, '{}'::jsonb, '2026-10-31T10:00:00.000Z', '2026-10-31T10:00:00.000Z'),
  ('00000001-0003-4000-8000-000000000011', '00000001-0000-4000-8000-000000000001', 'Paithani (coming soon)', 'unreleased-paithani', 'Draft product: must never appear on the storefront.', 'fixed', 3200000, null, 'draft', '{"fabric":"Silk","colour":"Green"}'::jsonb, false, '{}'::jsonb, '2026-11-15T10:00:00.000Z', '2026-11-15T10:00:00.000Z'),
  ('00000002-0003-4000-8000-000000000001', '00000002-0000-4000-8000-000000000001', 'Sage Chanderi Kurta Set', 'sage-chanderi-kurta-set', 'A straight Chanderi kurta in sage with delicate gota detailing, paired with cotton pants and a sheer dupatta.', 'fixed', 429000, null, 'active', '{"fabric":"Chanderi silk-cotton","colour":"Green","fit":"Straight, relaxed","length":"Calf length","includes":"Kurta, pants, dupatta","care":"Gentle hand wash, dry in shade"}'::jsonb, true, '{}'::jsonb, '2026-11-11T10:00:00.000Z', '2026-11-11T10:00:00.000Z'),
  ('00000002-0003-4000-8000-000000000002', '00000002-0000-4000-8000-000000000001', 'Ivory Chikankari Kurta Set', 'ivory-chikankari-kurta-set', 'Hand-embroidered Lucknowi chikankari on soft mul, with a scalloped hem and matching palazzos.', 'fixed', 589000, 699000, 'active', '{"fabric":"Mul cotton","colour":"Ivory","fit":"A-line","length":"Knee length","includes":"Kurta, palazzo","care":"Gentle hand wash, dry in shade"}'::jsonb, true, '{}'::jsonb, '2026-10-26T10:00:00.000Z', '2026-10-26T10:00:00.000Z'),
  ('00000002-0003-4000-8000-000000000003', '00000002-0000-4000-8000-000000000001', 'Terracotta Block-Print Kurta Set', 'terracotta-block-print-kurta-set', 'Hand block-printed in Sanganer with natural dyes, finished with wooden buttons.', 'fixed', 345000, null, 'active', '{"fabric":"Cotton cambric","colour":"Orange","fit":"Straight","length":"Calf length","includes":"Kurta, pants","care":"Gentle hand wash, dry in shade"}'::jsonb, false, '{}'::jsonb, '2026-10-13T10:00:00.000Z', '2026-10-13T10:00:00.000Z'),
  ('00000002-0003-4000-8000-000000000004', '00000002-0000-4000-8000-000000000001', 'Midnight Velvet Anarkali', 'midnight-velvet-anarkali', 'A floor-length micro-velvet anarkali with zardozi at the yoke. Made for winter weddings.', 'fixed', 890000, null, 'active', '{"fabric":"Micro velvet","colour":"Blue","fit":"Flared","length":"Floor length","includes":"Anarkali, churidar, dupatta","care":"Dry clean only"}'::jsonb, true, '{}'::jsonb, '2026-11-05T10:00:00.000Z', '2026-11-05T10:00:00.000Z'),
  ('00000002-0003-4000-8000-000000000005', '00000002-0000-4000-8000-000000000001', 'Blush Tiered Anarkali', 'blush-tiered-anarkali', 'Three soft tiers of georgette in blush pink, with a hand-embroidered neckline.', 'fixed', 725000, null, 'active', '{"fabric":"Georgette","colour":"Pink","fit":"Flared","length":"Ankle length","includes":"Anarkali, pants, dupatta","care":"Dry clean only"}'::jsonb, false, '{}'::jsonb, '2026-10-18T10:00:00.000Z', '2026-10-18T10:00:00.000Z'),
  ('00000002-0003-4000-8000-000000000006', '00000002-0000-4000-8000-000000000001', 'Emerald Georgette Anarkali', 'emerald-georgette-anarkali', 'Emerald georgette with a sequinned yoke and a sweeping 4-metre flare.', 'fixed', 680000, 790000, 'active', '{"fabric":"Georgette","colour":"Green","fit":"Flared","length":"Floor length","includes":"Anarkali, dupatta","care":"Dry clean only"}'::jsonb, false, '{}'::jsonb, '2026-10-01T10:00:00.000Z', '2026-10-01T10:00:00.000Z'),
  ('00000002-0003-4000-8000-000000000007', '00000002-0000-4000-8000-000000000001', 'Champagne Sequin Lehenga', 'champagne-sequin-lehenga', 'Our signature bridal lehenga, covered in hand-placed sequins. Made to measure; price confirmed on WhatsApp.', 'on_request', null, null, 'active', '{"fabric":"Net with silk lining","colour":"Gold","fit":"Made to measure","includes":"Lehenga, blouse, dupatta","care":"Dry clean only"}'::jsonb, true, '{}'::jsonb, '2026-11-09T10:00:00.000Z', '2026-11-09T10:00:00.000Z'),
  ('00000002-0003-4000-8000-000000000008', '00000002-0000-4000-8000-000000000001', 'Rani Pink Lehenga', 'rani-pink-lehenga', 'Rani pink raw silk with gota patti borders and a mirror-work blouse.', 'fixed', 2490000, null, 'active', '{"fabric":"Raw silk","colour":"Pink","fit":"Flared","includes":"Lehenga, blouse, dupatta","care":"Dry clean only"}'::jsonb, false, '{}'::jsonb, '2026-11-01T10:00:00.000Z', '2026-11-01T10:00:00.000Z'),
  ('00000002-0003-4000-8000-000000000009', '00000002-0000-4000-8000-000000000001', 'Pastel Mint Lehenga', 'pastel-mint-lehenga', 'A light organza lehenga in mint with tonal thread work, made for day functions.', 'fixed', 1850000, null, 'active', '{"fabric":"Organza","colour":"Green","fit":"Flared","includes":"Lehenga, blouse, dupatta","care":"Dry clean only"}'::jsonb, false, '{}'::jsonb, '2026-10-08T10:00:00.000Z', '2026-10-08T10:00:00.000Z'),
  ('00000002-0003-4000-8000-00000000000a', '00000002-0000-4000-8000-000000000001', 'Ikat Co-ord Set', 'ikat-co-ord', 'A boxy shirt and wide-leg pants in handwoven Pochampally ikat. Choose indigo or rust.', 'fixed', 399000, null, 'active', '{"fabric":"Handwoven cotton ikat","colour":"Blue","fit":"Relaxed","includes":"Shirt, pants","care":"Gentle hand wash, dry in shade"}'::jsonb, true, '{}'::jsonb, '2026-11-12T10:00:00.000Z', '2026-11-12T10:00:00.000Z'),
  ('00000002-0003-4000-8000-00000000000b', '00000002-0000-4000-8000-000000000001', 'Linen Lounge Co-ord', 'linen-lounge-co-ord', 'Washed linen in oat, with a relaxed kurta-shirt and drawstring pants.', 'fixed', 329000, null, 'active', '{"fabric":"Washed linen","colour":"Natural","fit":"Relaxed","includes":"Top, pants","care":"Machine wash gentle"}'::jsonb, false, '{}'::jsonb, '2026-11-03T10:00:00.000Z', '2026-11-03T10:00:00.000Z'),
  ('00000002-0003-4000-8000-00000000000c', '00000002-0000-4000-8000-000000000001', 'Olive Utility Co-ord', 'olive-utility-co-ord', 'Cotton twill in olive, with patch pockets and a tie belt. Made for travel.', 'fixed', 365000, null, 'active', '{"fabric":"Cotton twill","colour":"Green","fit":"Relaxed","includes":"Shirt, pants","care":"Machine wash gentle"}'::jsonb, false, '{}'::jsonb, '2026-09-24T10:00:00.000Z', '2026-09-24T10:00:00.000Z'),
  ('00000002-0003-4000-8000-00000000000d', '00000002-0000-4000-8000-000000000001', 'Mulmul Printed Co-ord', 'mulmul-printed-co-ord', 'Featherlight mulmul with a peach floral print. Our coolest set for summer.', 'fixed', 289000, null, 'active', '{"fabric":"Mulmul cotton","colour":"Orange","fit":"Relaxed","includes":"Top, pants","care":"Gentle hand wash, dry in shade"}'::jsonb, false, '{}'::jsonb, '2026-10-22T10:00:00.000Z', '2026-10-22T10:00:00.000Z'),
  ('00000002-0003-4000-8000-00000000000e', '00000002-0000-4000-8000-000000000001', 'Gota Patti Dupatta', 'gota-patti-dupatta', 'Marigold chiffon dupatta with gota patti borders and tassels.', 'fixed', 215000, null, 'active', '{"fabric":"Chiffon","colour":"Yellow","length":"2.5 m","care":"Dry clean only"}'::jsonb, false, '{}'::jsonb, '2026-11-06T10:00:00.000Z', '2026-11-06T10:00:00.000Z'),
  ('00000002-0003-4000-8000-00000000000f', '00000002-0000-4000-8000-000000000001', 'Bandhani Silk Dupatta', 'bandhani-silk-dupatta', 'Hand-tied bandhani on gaji silk from Kutch, in a deep festive red.', 'fixed', 289000, null, 'active', '{"fabric":"Gaji silk","colour":"Red","length":"2.4 m","care":"Dry clean only"}'::jsonb, true, '{}'::jsonb, '2026-10-29T10:00:00.000Z', '2026-10-29T10:00:00.000Z'),
  ('00000002-0003-4000-8000-000000000010', '00000002-0000-4000-8000-000000000001', 'Organza Floral Dupatta', 'organza-floral-dupatta', 'Sheer pink organza with printed florals and a lace edge.', 'fixed', 195000, 240000, 'active', '{"fabric":"Organza","colour":"Pink","length":"2.4 m","care":"Dry clean only"}'::jsonb, false, '{}'::jsonb, '2026-10-05T10:00:00.000Z', '2026-10-05T10:00:00.000Z');
